import sys, os
from elftools.elf.elffile import ELFFile
from capstone import *
from capstone.arm64 import *

def load(path):
    f=ELFFile(open(path,'rb'))
    # collect exec sections (multiple .text allowed)
    texts=[]
    for sec in f.iter_sections():
        if sec['sh_flags'] & 0x4 and sec['sh_size']>0 and sec['sh_type']=='SHT_PROGBITS':
            texts.append((sec['sh_addr'], sec.data()))
    dyn=f.get_section_by_name('.dynsym')
    syms=list(dyn.iter_symbols())
    rp=f.get_section_by_name('.rela.plt')
    # PLT location: smallest exec PROGBITS section address (observed layout)
    plt_addr=min(a for a,_ in texts)
    relocs=list(rp.iter_relocations()) if rp else []
    # GOT slots from rela.dyn too (for fns bound without plt)
    rd=f.get_section_by_name('.rela.dyn')
    got_direct={}  # got addr -> name
    if rd:
        for r in rd.iter_relocations():
            try: nm=syms[r['r_info_sym']].name
            except: continue
            if nm: got_direct[r['r_offset']]=nm
    # function map from symtab
    funcs=[]
    st=f.get_section_by_name('.symtab')
    if st:
        for s in st.iter_symbols():
            if s['st_info']['type']=='STT_FUNC' and s['st_value'] and s['st_size']:
                funcs.append((s['st_value'], s['st_value']+s['st_size'], s.name))
    funcs.sort()
    return f,texts,plt_addr,relocs,syms,got_direct,funcs

def find_func(funcs,addr):
    import bisect
    starts=[a for a,_,_ in funcs]
    i=bisect.bisect_right(starts,addr)-1
    if i>=0 and funcs[i][0]<=addr<funcs[i][1]:
        return funcs[i][2]
    return None

def scan(path, want):
    f,texts,plt_addr,relocs,syms,got_direct,funcs=load(path)
    # map plt stub -> name
    plt_map={}
    for i,r in enumerate(relocs):
        nm=syms[r['r_info_sym']].name
        if nm in want:
            plt_map[plt_addr+0x20+i*0x10]=nm
    # also want got slots for direct loads
    want_got={g:n for g,n in got_direct.items() if n in want}
    md=Cs(CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN)
    md.detail=True
    results=[]
    for base,data in texts:
        # skip PLT region itself
        for insn in md.disasm(data, base):
            if insn.mnemonic=='bl':
                t=insn.operands[0].imm
                if t in plt_map:
                    results.append((insn.address, plt_map[t], 'bl-plt'))
            elif insn.mnemonic=='adrp':
                # check following ldr within 3 insns for want_got
                pass
    return results, funcs

if __name__=='__main__':
    path=sys.argv[1]
    want=set(sys.argv[2].split(','))
    res,funcs=scan(path,want)
    import bisect
    for addr,name,how in res:
        fn=find_func(funcs,addr)
        print(hex(addr), name, how, fn if fn else '?')
