elff=ELFFile(io.BytesIO(data))
def read_str(vaddr):
    for seg in elff.iter_segments():
        if seg['p_type']=='PT_LOAD':
            a=seg['p_vaddr']; sz=seg['p_filesz']
            if a<=vaddr<a+sz:
                o=seg['p_offset']+vaddr-a
                end=data.find(b'\0',o)
                return data[o:end].decode(errors='replace')
